'use client';

import { useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import type { CSSProperties } from 'react';
import './image-hotspots.css';

export interface ImageHotspotItem {
  id: string;
  label: string;
  /** Horizontal position in the uncropped image, from 0 to 1. */
  x: number;
  /** Vertical position in the uncropped image, from 0 to 1. */
  y: number;
  title?: string;
  description?: string;
  price?: string;
  action?: { label: string; href: string };
}

export interface ImageHotspotsProps {
  image: string;
  alt: string;
  items: ImageHotspotItem[];
  caption?: string;
  defaultActiveId?: string;
  onActiveChange?: (item: ImageHotspotItem | null) => void;
  className?: string;
}

function coordinate(value: number) {
  return Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0.5;
}

/** Image annotations with native disclosure controls and bounded detail cards. */
export function ImageHotspots({ image, alt, items, caption, defaultActiveId, onActiveChange, className = '' }: ImageHotspotsProps) {
  const [activeId, setActiveId] = useState<string | null>(defaultActiveId ?? null);
  const [position, setPosition] = useState({ left: 12, top: 12, maxHeight: 10000 });
  const root = useRef<HTMLElement>(null);
  const stage = useRef<HTMLDivElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const triggers = useRef(new Map<string, HTMLButtonElement>());
  const instance = useId();
  const panelId = `ac-hotspot-panel-${instance}`;
  const titleId = `${panelId}-title`;
  const active = items.find(item => item.id === activeId);

  function close(restoreFocus = false) {
    if (!active) return;
    setActiveId(null);
    onActiveChange?.(null);
    if (restoreFocus) triggers.current.get(active.id)?.focus({ preventScroll: true });
  }

  useEffect(() => {
    if (!active) return;
    function onPointerDown(event: PointerEvent) {
      if (!root.current?.contains(event.target as Node)) close();
    }
    function onFocusIn(event: FocusEvent) {
      if (!root.current?.contains(event.target as Node)) close();
    }
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape' && !event.defaultPrevented && root.current?.contains(document.activeElement)) {
        event.preventDefault();
        close(true);
      }
    }
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('focusin', onFocusIn);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('focusin', onFocusIn);
      document.removeEventListener('keydown', onKeyDown);
    };
  });

  useLayoutEffect(() => {
    if (!active || !stage.current || !panel.current) return;
    const currentStage = stage.current;
    const currentPanel = panel.current;
    function measure() {
      const width = currentStage.clientWidth;
      const height = currentStage.clientHeight;
      if (width < 560) return;
      const cardWidth = currentPanel.offsetWidth;
      const maxHeight = Math.max(0, height - 24);
      const cardHeight = Math.min(currentPanel.offsetHeight, maxHeight);
      const x = coordinate(active!.x) * width;
      const y = coordinate(active!.y) * height;
      const side = width - x >= x ? x + 28 : x - cardWidth - 28;
      const left = Math.max(12, Math.min(side, width - cardWidth - 12));
      const top = Math.max(12, Math.min(y - cardHeight / 2, height - cardHeight - 12));
      setPosition(previous => previous.left === left && previous.top === top && previous.maxHeight === maxHeight ? previous : { left, top, maxHeight });
    }
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(currentStage);
    observer.observe(currentPanel);
    return () => observer.disconnect();
  }, [active]);

  return <figure ref={root} className={`ac-image-hotspots ${className}`.trim()}>
    <div ref={stage} className="ac-hotspots-stage">
      <img className="ac-hotspots-image" src={image} alt={alt} loading="lazy" decoding="async" draggable={false} />
      {items.map((item, index) => <button
        key={item.id}
        ref={element => { if (element) triggers.current.set(item.id, element); else triggers.current.delete(item.id); }}
        type="button"
        className={`ac-hotspot-trigger${item.id === active?.id ? ' is-active' : ''}${coordinate(item.x) > 0.85 ? ' is-edge' : ''}`}
        style={{ '--ac-hotspot-x': `${coordinate(item.x) * 100}%`, '--ac-hotspot-y': `${coordinate(item.y) * 100}%` } as CSSProperties}
        aria-label={item.label}
        aria-expanded={item.id === active?.id}
        aria-controls={item.id === active?.id ? panelId : undefined}
        onClick={() => {
          const next = item.id === active?.id ? null : item;
          setActiveId(next?.id ?? null);
          onActiveChange?.(next);
        }}
      ><span className="ac-hotspot-marker" aria-hidden="true"><span /></span><span className="ac-hotspot-number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span></button>)}
    </div>
    {active && <div
      ref={panel}
      id={panelId}
      role="region"
      aria-labelledby={titleId}
      className="ac-hotspot-panel"
      style={{ '--ac-hotspot-panel-left': `${position.left}px`, '--ac-hotspot-panel-top': `${position.top}px`, '--ac-hotspot-panel-max-height': `${position.maxHeight}px` } as CSSProperties}
    >
      <div className="ac-hotspot-panel-top"><span>{String(items.findIndex(item => item.id === active.id) + 1).padStart(2, '0')}</span><button type="button" aria-label={`Close ${active.label}`} onClick={() => close(true)}><span aria-hidden="true">×</span></button></div>
      <h3 id={titleId}>{active.title ?? active.label}</h3>
      {active.description && <p>{active.description}</p>}
      {(active.price || active.action) && <div className="ac-hotspot-panel-bottom">{active.price && <span>{active.price}</span>}{active.action && <a href={active.action.href}>{active.action.label}<span aria-hidden="true">↗</span></a>}</div>}
    </div>}
    {caption && <figcaption className="ac-hotspots-caption">{caption}</figcaption>}
  </figure>;
}

.ac-image-hotspots,
.ac-image-hotspots * { box-sizing: border-box; }
.ac-image-hotspots {
  container: ac-hotspots / inline-size;
  position: relative;
  width: 100%;
  margin: 0;
  color: var(--ac-hotspots-ink, #292d28);
  font-family: Arial, Helvetica, sans-serif;
  text-align: left;
}
.ac-hotspots-stage { position: relative; width: 100%; min-width: 0; isolation: isolate; }
.ac-hotspots-image { display: block; width: 100%; height: auto; margin: 0; user-select: none; }
.ac-hotspot-trigger {
  position: absolute;
  z-index: 1;
  left: clamp(23px, var(--ac-hotspot-x), calc(100% - 23px));
  top: clamp(23px, var(--ac-hotspot-y), calc(100% - 23px));
  display: grid;
  width: 46px;
  height: 46px;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: #fff;
  transform: translate(-50%, -50%);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.ac-hotspot-marker { display: grid; width: 31px; height: 31px; place-items: center; border: 1px solid #ffffffc4; border-radius: 50%; background: #262b2866; box-shadow: 0 0 0 6px #ffffff1f; backdrop-filter: blur(6px); transition: background 180ms, box-shadow 180ms; }
.ac-hotspot-marker > span { position: relative; width: 10px; height: 10px; }
.ac-hotspot-marker > span::before,
.ac-hotspot-marker > span::after { position: absolute; top: 4.5px; left: 0; width: 10px; height: 1px; background: currentColor; content: ''; }
.ac-hotspot-marker > span::after { transform: rotate(90deg); transition: transform 180ms; }
.ac-hotspot-trigger.is-active .ac-hotspot-marker { background: var(--ac-hotspots-accent, #a84f32); box-shadow: 0 0 0 6px #a84f3233; }
.ac-hotspot-trigger.is-active .ac-hotspot-marker > span::after { transform: rotate(0); }
.ac-hotspot-trigger:hover .ac-hotspot-marker { box-shadow: 0 0 0 8px #ffffff30; }
.ac-hotspot-trigger:focus-visible { outline: 2px solid white; outline-offset: 2px; box-shadow: 0 0 0 5px #292d28; }
.ac-hotspot-number { position: absolute; top: 4px; left: 40px; color: white; font: 9px/1 ui-monospace, monospace; text-shadow: 0 1px 3px #000a; }
.ac-hotspot-trigger.is-edge .ac-hotspot-number { left: auto; right: 40px; }
.ac-hotspot-panel {
  position: absolute;
  z-index: 3;
  top: var(--ac-hotspot-panel-top, 12px);
  left: var(--ac-hotspot-panel-left, 12px);
  width: min(270px, calc(100% - 24px));
  max-height: min(var(--ac-hotspot-panel-max-height, 10000px), calc(100% - 24px));
  overflow-y: auto;
  padding: 18px;
  border: 1px solid #292d2817;
  background: var(--ac-hotspots-surface, #f6f4ee);
  box-shadow: 0 10px 30px #20221c17;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
  animation: ac-hotspot-enter 180ms ease-out;
}
.ac-hotspot-panel-top { display: flex; min-height: 26px; align-items: start; justify-content: space-between; gap: 12px; }
.ac-hotspot-panel-top > span { color: var(--ac-hotspots-accent, #a84f32); font: 10px/1.4 ui-monospace, monospace; }
.ac-hotspot-panel-top > button { display: grid; width: 32px; height: 32px; margin: -8px -8px 0 0; padding: 0; place-items: center; border: 0; background: transparent; color: inherit; cursor: pointer; font: 24px/1 Arial, sans-serif; }
.ac-hotspot-panel h3 { margin: 6px 0 0; color: inherit; font: 400 23px/1.12 Georgia, serif; letter-spacing: -.035em; }
.ac-hotspot-panel p { margin: 10px 0 0; color: var(--ac-hotspots-muted, #676b60); font-size: 12px; line-height: 1.65; }
.ac-hotspot-panel-bottom { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; margin-top: 19px; padding-top: 13px; border-top: 1px solid var(--ac-hotspots-line, #d8d9d0); font-size: 12px; }
.ac-hotspot-panel-bottom a { display: inline-flex; justify-content: space-between; align-items: center; gap: 20px; padding-block: 5px; color: inherit; text-decoration-thickness: 1px; text-underline-offset: 4px; }
.ac-hotspot-panel-bottom a > span { font-size: 18px; }
.ac-hotspot-panel button:focus-visible,
.ac-hotspot-panel a:focus-visible { outline: 2px solid var(--ac-hotspots-accent, #a84f32); outline-offset: 3px; }
.ac-hotspots-caption { padding-top: 13px; color: var(--ac-hotspots-muted, #676b60); font: 10px/1.5 ui-monospace, monospace; }
@container ac-hotspots (width < 560px) {
  .ac-hotspot-panel { position: relative; top: auto; left: auto; width: 100%; max-height: none; margin: 0; padding: 16px 18px 20px; border-top: 0; box-shadow: none; }
  .ac-hotspot-panel h3 { margin-top: 2px; font-size: 22px; }
  .ac-hotspot-panel p { max-width: 48ch; }
  .ac-hotspot-panel-top { min-height: 22px; }
}
@keyframes ac-hotspot-enter { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) {
  .ac-hotspot-panel { animation: none; }
  .ac-hotspot-marker,
  .ac-hotspot-marker > span::after { transition: none; }
}
@media (forced-colors: active) {
  .ac-hotspot-marker { border: 1px solid ButtonText; background: ButtonFace; color: ButtonText; }
  .ac-hotspot-marker > span::before,
  .ac-hotspot-marker > span::after { background: ButtonText; }
  .ac-hotspot-panel { border: 1px solid CanvasText; }
}

/* Photograph and over-image markers stay unchanged; the detail panel follows the theme. */
:where([data-theme="dark"], .dark) .ac-image-hotspots { --ac-hotspots-ink: #efefe8; --ac-hotspots-surface: #22251f; --ac-hotspots-muted: #b4b8aa; --ac-hotspots-line: #4b5043; --ac-hotspots-accent: #d49a82; }
:where([data-theme="dark"], .dark) .ac-hotspot-panel { border-color: #4b5043; box-shadow: 0 10px 30px #0005; }
:where([data-theme="dark"], .dark) .ac-hotspot-trigger.is-active .ac-hotspot-marker { background: #a84f32; }
:where([data-theme="dark"], .dark) .ac-hotspot-panel-top > button:hover { background: #ffffff0d; }
